using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ─── CalculateTotal: DataRow-driven tests ───────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate exceeds 1")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ─── ApplyDiscount: DynamicData-driven tests ────────────────────────────

    public static IEnumerable<object[]> ValidDiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m };   // No discount
            yield return new object[] { 100.00m, 10m, 90.00m };   // 10% off
            yield return new object[] { 100.00m, 50m, 50.00m };   // 50% off
            yield return new object[] { 100.00m, 100m, 0.00m };   // Full discount
            yield return new object[] { 49.99m, 25m, 37.4925m };  // Fractional result
            yield return new object[] { 0.00m, 50m, 0.00m };      // Zero price
            yield return new object[] { 200.00m, 33.33m, 133.34m }; // Repeating decimal %
        }
    }

    [TestMethod]
    [DynamicData(nameof(ValidDiscountCases))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> InvalidDiscountCases
    {
        get
        {
            yield return new object[] { 100.00m, -1m };    // Below 0
            yield return new object[] { 100.00m, 100.01m }; // Above 100
            yield return new object[] { 50.00m, -50m };    // Far below 0
            yield return new object[] { 50.00m, 200m };    // Far above 100
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases))]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    // ─── FormatPrice: DataRow-driven tests ──────────────────────────────────

    [TestMethod]
    [DataRow(10.00, "$", "$10.00", DisplayName = "Default currency")]
    [DataRow(10.456, "$", "$10.46", DisplayName = "Rounds to 2 decimals")]
    [DataRow(0.00, "€", "€0.00", DisplayName = "Zero with euro symbol")]
    [DataRow(1234.50, "£", "£1234.50", DisplayName = "Large value with pound")]
    public void FormatPrice_WithValidInputs_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

